 async function previewBatchImport(){const links=[...new Set(importLinks.split(/\r?\n/).map(v=>v.trim()).filter(Boolean))];if(!links.length){setNotice('Cole pelo menos um link, um por linha.');return;}if(links.length>30){setNotice('O limite é de 30 links por importação.');return;}setImporting(true);setImportResults([]);const results=[];for(let i=0;i<links.length;i++){const link=links[i];if(products.some(p=>(p.url||'').trim()===link)){results.push({url:link,ok:false,duplicate:true,error:'Este link já está cadastrado.'});setImportResults([...results]);continue;}try{const {data,error}=await supabase.functions.invoke('cssbuy-product-lookup',{body:{url:link}});if(error)throw new Error(error.message||'Falha na consulta.');if(!data?.ok)throw new Error(data?.error||'Produto não encontrado.');results.push({url:link,ok:true,title:data.title||'Produto importado',image_url:data.image_url||null,price_cny:Number(data.price_cny)||null,platform:data.platform||'CSSBuy'});}catch(err){results.push({url:link,ok:false,error:err?.message||'Erro na consulta.'});}setImportResults([...results]);}setImporting(false);setNotice('Consulta em lote concluída. Revise os produtos encontrados antes de salvar.');}
 async function saveBatchImport(){const valid=importResults.filter(r=>r.ok);if(!valid.length){setNotice('Nenhum produto válido para importar.');return;}setSavingImport(true);const rows=valid.map(r=>({user_id:session.user.id,title:r.title,url:r.url,status:'Link salvo',price:r.price_cny!=null?Number((r.price_cny/Math.max(0.0001,Number(cnyRate)||1.04)).toFixed(2)):null,original_price_cny:r.price_cny,extra_cost:null,category:null,brand:null,size:null,color:null,qc_url:null,notes:null,tags:[],is_wishlist:false}));const {data,error}=await supabase.from('products').insert(rows).select();if(error){setSavingImport(false);setNotice('Erro ao salvar importação: '+error.message);return;}let importWarning='';const variantsToInsert=(data||[]).map((p,i)=>valid[i]?.image_url?({product_id:p.id,user_id:session.user.id,name:'Principal',image_url:valid[i].image_url,is_primary:true}):null).filter(Boolean);if(variantsToInsert.length){const {error:variantError}=await supabase.from('product_variants').insert(variantsToInsert);if(variantError)importWarning='Produtos importados, mas algumas imagens não foram salvas: '+variantError.message;}const historyRows=(data||[]).map(p=>({product_id:p.id,user_id:session.user.id,status:'Link salvo'}));if(historyRows.length){const {error:historyError}=await supabase.from('product_status_history').insert(historyRows);if(historyError)importWarning='Produtos importados, mas o histórico inicial não foi salvo: '+historyError.message;}await logActivity('batch_import','product',null,valid.length+' produtos importados em lote',{count:valid.length});setSavingImport(false);setShowImportModal(false);setImportLinks('');setImportResults([]);setNotice(importWarning||valid.length+' produtos importados com sucesso.');await loadProducts();}
 async function lookupCssbuyPrice(){setCssbuyPriceOptions([]);if(!form.url?.trim()){setNotice('Cole primeiro o link do produto (CSSBuy, 1688 ou Weidian).');return;}setLookingUpPrice(true);setNotice('Identificando o anúncio e consultando os preços...');try{const {data,error}=await supabase.functions.invoke('cssbuy-product-lookup',{body:{url:form.url.trim()}});if(error){let message=error.message||'Falha na consulta.';try{const details=await error.context?.json();if(details?.error)message=details.error;}catch{}setNotice('Não foi possível buscar o preço: '+message);return;}if(!data?.ok){setNotice(data?.error||'O provedor não retornou um preço. Você pode preencher manualmente.');return;}const options=Array.isArray(data.price_options)?data.price_options:[];setCssbuyPriceOptions(options);setForm(f=>({...f,original_price_cny:options.length===1?String(options[0]):options.length>1?'':String(data.price_cny)}));setNotice(options.length>1?'Encontramos vários preços. Escolha o correspondente à sua opção.':'Preço encontrado: ¥ '+Number(data.price_cny).toFixed(2)+' ('+(data.platform||'produto')+').');}catch(err){setNotice('Erro ao consultar o anúncio: '+(err?.message||'tente novamente.'));}finally{setLookingUpPrice(false);}}
 async function openDetails(p){setDetailProduct(p);setLoadingHistory(true);const {data,error}=await supabase.from('product_status_history').select('*').eq('product_id',p.id).order('changed_at',{ascending:false});setLoadingHistory(false);if(error){setStatusHistory([]);setNotice('Não foi possível carregar o histórico: '+error.message);return;}setStatusHistory(data||[])}
 async function addProduct(e){e.preventDefault();if(!supabase){setNotice('Configure o Supabase primeiro.');return;}const {image_url,...fields}=form;const payload={...fields,title:fields.title.trim(),price:fields.price===''?null:Number(fields.price),original_price_cny:fields.original_price_cny===''?null:Number(fields.original_price_cny),extra_cost:fields.extra_cost===''?null:Number(fields.extra_cost),size:fields.size.trim()||null,color:fields.color.trim()||null,brand:fields.brand.trim()||null,tags:(fields.tags||'').split(',').map(t=>t.trim()).filter(Boolean)};if(editingProduct){const {error}=await supabase.from('products').update(payload).eq('id',editingProduct.id);if(error){setNotice(error.message);return;}await logActivity('update','product',editingProduct.id,'Produto editado: '+payload.title);if(editingProduct.status!==payload.status){await logActivity('status_changed','product',editingProduct.id,'Status alterado: '+payload.title+' → '+payload.status,{status:payload.status});const {error:he}=await supabase.from('product_status_history').insert({product_id:editingProduct.id,user_id:session.user.id,status:payload.status});if(he)setNotice('Produto atualizado, mas não foi possível registrar o histórico: '+he.message);else setNotice('Produto atualizado.');}else setNotice('Produto atualizado.');}else{const {data,error}=await supabase.from('products').insert({...payload,user_id:session.user.id}).select().single();if(error){setNotice(error.message);return;}await logActivity('create','product',data.id,'Produto adicionado: '+payload.title);const {error:he}=await supabase.from('product_status_history').insert({product_id:data.id,user_id:session.user.id,status:payload.status});if(he)setNotice('Produto salvo, mas o histórico não foi registrado: '+he.message);if(image_url?.trim()){const {error:ve}=await supabase.from('product_variants').insert({product_id:data.id,user_id:session.user.id,name:'Principal',image_url:image_url.trim(),is_primary:true});if(ve)setNotice('Produto salvo; erro na imagem: '+ve.message);}else if(!he)setNotice('Produto adicionado.');}setForm({title:'',url:'',price:'',original_price_cny:'',status:'Link salvo',qc_url:'',notes:'',image_url:'',category:'',brand:'',size:'',color:'',extra_cost:'',tags:'',is_wishlist:false});setEditingProduct(null);setShowAdd(false);loadProducts();}
