 async function toggleWishlist(p){const {error}=await supabase.from('products').update({is_wishlist:!p.is_wishlist}).eq('id',p.id);if(error){setNotice(error.message);return;}await logActivity('wishlist','product',p.id,p.is_wishlist?'Removido da lista de desejos: '+p.title:'Adicionado à lista de desejos: '+p.title);setNotice(p.is_wishlist?'Removido da lista de desejos.':'Adicionado à lista de desejos.');loadProducts()}
